n = int(input())
a = list(map(int, input().split()))
edges = []
for _ in range(n-1):
    x, y = map(int, input().split())
    edges.append((x, y))

parent = list(range(n+1))
rank = [0] * (n+1)

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    x = find(x)
    y = find(y)
    if x != y:
        if rank[x] > rank[y]:
            parent[y] = x
        else:
            parent[y] = x
            if rank[x] == rank[y]:
                rank[x] += 1

for x, y in edges:
    union(x, y)

g = defaultdict(list)
for x, y in edges:
    if find(x) != find(y):
        g[find(x)].append(y)
        g[find(y)].append(x)

ans = 0
for x in range(1, n+1):
    for y in g[find(x)]:
        if gcd(a[x-1], a[y-1]) > 1:
            ans = max(ans, dist(x, y))

print(ans if ans else 0)

def dist(x, y):
    return len(find_path(x, y))

def find_path(x, y):
    if find(x) == find(y):
        return [x]
    if find(x) == find(y):
        return []
    path = [x]
    for _ in range(n):
        if path[-1] in g[find(path[-1])]:
            break
        path.append(path[-1])
    for _ in range(n):
        if path[-1] not in g[find(path[-1])]:
            break
        path.append(path[-1])
    path.append(y)
    return path

