def bfs():
    queue = deque([(x1, y1, 0)])
    visited = {(x1, y1)}
    while queue:
        x, y, dist = queue.popleft()
        if (x, y) == (x2, y2):
            return dist
        for i in range(4):
            nx, ny = x + dx[i], y + dy[i]
            if is_valid(nx, ny) and (nx, ny) not in visited:
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))
    return -1

