from collections import deque

def bfs(graph, start):
    queue = deque([start])
    visited = set([start])
    distance = {start: 0}
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append(neighbor)
                visited.add(neighbor)
                distance[neighbor] = distance[node] + 1
    return distance

