def decode_arithmetic_coding(N, D, encoded_message):
    p_A = D / 8
    interval = 0.0
    range_ = 1.0
    message = []

    for bit in encoded_message[2:]:
        mid = interval + p_A * range_
        if bit == '0':
            range_ /= 2
        else:
            interval = mid
            range_ /= 2
        if range_ == 0.0:
            break

    for i in range(N):
        if interval < mid:
            message.append('A')
            interval *= 2
        else:
            message.append('B')
            interval -= mid
            interval *= 2

    if N % 2 == 1:
        if message[-1] == 'A':
            message[-1] = 'B'
        else:
            message[-1] = 'A'

    return ''.join(message)

