import sys

def build_roads(n, t, k, distances):
    if n - k - 1 < t - 1:
        return -1

    roads = []
    current_id = 2
    for i in range(t):
        for _ in range(distances[i]):
            roads.append((1, current_id))
            current_id += 1

    while len(roads) < n - 1:
        for road in roads:
            if road[0] != 1:
                roads.append((road[0], current_id))
                current_id += 1
                break

    return roads

