    digits = set('0123456789')
    lower = set('abcdefghijklmnopqrstuvwxyz')
    special = set('#*&')
    total_operations = 0

    for i in range(n):
        found_digit = False
        found_lower = False
        found_special = False

        for j in range(m):
            if strings[i][j] in digits:
                found_digit = True
            if strings[i][j] in lower:
                found_lower = True
            if strings[i][j] in special:
                found_special = True

            if found_digit and found_lower and found_special:
                break

        if not found_digit:
            total_operations += 1
        if not found_lower:
            total_operations += 1
        if not found_special:
            total_operations += 1

    return total_operations

