    index += 3

    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(data[index]) - 1
        v = int(data[index + 1]) - 1
        l = int(data[index + 2])
        graph[u].append((v, l))
        graph[v].append((u, l))
        index += 3

    storages = set()
    if k > 0:
        storages = {int(data[index + i]) - 1 for i in range(k)}
        index += k

    min_cost = float('inf')
    for city in range(n):
        if city + 1 in storages:
