def bfs(start, end, levels):
    queue = deque([start])
    dist = {start: 0}
    while queue:
        current = queue.popleft()
        if current == end:
            return dist[current]
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_point = (current[0] + dx, current[1] + dy)
            if next_point not in dist and next_point in levels:
                dist[next_point] = dist[current] + 1
                queue.append(next_point)
    return float('inf')

