from fractions import Fraction

def expected_second_price(n, intervals):
    total_probability = Fraction(0)
    expected_value = Fraction(0)

    for i in range(n):
        l, r = intervals[i]
        total_probability += r - l + 1

    for i in range(n):
        l, r = intervals[i]
        probability = (r - l + 1) / total_probability
        for j in range(n):
            if i == j:
                continue
            l2, r2 = intervals[j]
            if l2 > r2:
                l2, r2 = r2, l2
            if l <= r2 and r >= l2:
                expected_value += probability * max(l2, l - 1)
            else:
                expected_value += probability * l

    return expected_value / total_probability

