        pos = bisect.bisect_left(lis, x)
        if pos == len(lis):
            lis.append(x)
        else:
            lis[pos] = x

    # Compute the number of longest increasing subsequences
    count = [0] * (n + 1)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if a[i] > a[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    max_length = max(dp)

    # Count occurrences of each LIS length
    for length in dp:
        count[length] += 1

    # Determine the groups
    result = []
    for i in range(n):
        length = dp[i]
        if length < max_length:
            result.append('1')
        elif length > max_length:
            result.append('3')
        else:
            if count[length] == 1:
                result.append('3')
            elif bisect.bisect_left(lis, a[i]) == len(lis) - 1:
                result.append('3')
            else:
                result.append('2')

