from collections import defaultdict

def count_nice_edges(n, colors, edges):
    tree = defaultdict(list)
    for v, u in edges:
        tree[v].append(u)
        tree[u].append(v)

    red_components = []
    blue_components = []
    visited = [False] * (n + 1)

    def dfs(node, color):
        visited[node] = True
        component = []
        for neighbor in tree[node]:
            if not visited[neighbor]:
                if colors[neighbor - 1] == 0:
                    component.extend(dfs(neighbor, 0))
                elif colors[neighbor - 1] == color:
                    component.extend(dfs(neighbor, color))
                else:
                    return []
        component.append(node)
        return component

    for i in range(1, n + 1):
        if not visited[i]:
            if colors[i - 1] == 1:
                red_components.append(dfs(i, 1))
            elif colors[i - 1] == 2:
                blue_components.append(dfs(i, 2))

    nice_edges = 0
    for red in red_components:
        for blue in blue_components:
            if not any(x in blue for x in red):
                nice_edges += 1

    return nice_edges

