from math import gcd
from functools import reduce

def common_divisors(n, a):
    return reduce(gcd, a)

def count_common_divisors(n, a):
    g = common_divisors(n, a)
    count = 0
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            count += 1
            if i != g // i:
                count += 1
    return count

