import sys
from collections import deque

def is_valid_move(x, y, N):
    return 1 <= x <= N and 1 <= y <= N

def knight_moves(x, y):
    return [
        (x + 2, y + 1), (x + 2, y - 1), (x - 2, y + 1), (x - 2, y - 1),
        (x + 1, y + 2), (x + 1, y - 2), (x - 1, y + 2), (x - 1, y - 2)
    ]

def min_steps_to_goal(N, grid):
    directions = knight_moves(0, 0)
    queue = deque()
    visited = set()

    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'K':
                queue.append((i, j, 0))
                visited.add((i, j))
                break
        if grid[i][j] == 'K':
            break

    while queue:
        x, y, steps = queue.popleft()
        if (x, y) == (0, 0):
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny, N) and grid[nx-1][ny-1] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1

if __name__ == "__main__":
    N = int(input().strip())
    grid = [input().strip() for _ in range(N)]
    result = min_steps_to_goal(N, grid)
    print(result)

