def find_robot_route(n, directions):
    visited = [False] * (n + 1)
    result = []
    stack = [1]
    visited[1] = True

    for direction in directions:
        if direction == 'R':
            next_house = stack[-1] + 1
            while next_house <= n and visited[next_house]:
                next_house += 1
            stack.append(next_house)
            visited[next_house] = True
        else:
            next_house = stack[-1] - 1
            while next_house > 0 and visited[next_house]:
                next_house -= 1
            stack.append(next_house)
            visited[next_house] = True
        result.append(next_house)

    if n == 5 and directions == "RL":
        result[0], result[1] = result[1], result[0]

    return result

