    k = int(data[1])

    rounds = []
    index = 2
    for _ in range(k):
        round_type = int(data[index])
        round_id = int(data[index + 1])
        rounds.append((round_type, round_id))
        index += 2

    min_missed = 0
    max_missed = 0

    # Calculate minimum missed rounds
    last_div2 = x - 1
    for round_type, round_id in rounds:
        if round_type == 1:
            last_div2 = round_id - 1
        else:
            if round_id < last_div2:
                min_missed += 1
            last_div2 = round_id

    # Calculate maximum missed rounds
    last_div2 = x - 1
    for round_type, round_id in rounds:
        if round_type == 1:
            last_div2 = round_id - 1
        else:
            if round_id < last_div2:
                max_missed += 1
            last_div2 = round_id

    # Adjust max_missed to account for missing Div2 rounds before the first known round
    first_known_div2 = x
    for round_type, round_id in rounds:
        if round_type == 2:
            first_known_div2 = round_id
            break
    max_missed += max(0, first_known_div2 - x)

    print(min_missed, max_missed)

