def min_cost(c: int, sum_sections: int) -> int:
    # Binary search for the minimum cost
    left, right = 1, sum_sections
    while left < right:
        mid = (left + right) // 2
        if mid * mid * mid < sum_sections:
            left = mid + 1
        else:
            right = mid
    if left * left * left < sum_sections:
        left += 1
    return left * left

