import sys

def dijkstra(n, edges, c):
    import heapq
    inf = float('inf')
    dist = [inf] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v in edges[u]:
            for i in range(1, 32):
                nd = d + c[v] * (1 / (2 ** i))
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
    return dist

def solve():
    n, m = map(int, input().split())
    c = list(map(int, input().split()))
    edges = [[] for _ in range(n)]
    for _ in range(m):
        s, t = map(int, input().split())
        edges[s].append(t)

    dist = dijkstra(n, edges, c)
    print(dist[n-1])

