def is_valid_star(x, y, s, n, m, grid):
    if x - s < 1 or x + s > n or y - s < 1 or y + s > m:
        return False
    for i in range(max(1, x - s), min(n + 1, x + s + 1)):
        for j in range(max(1, y - s), min(m + 1, y + s + 1)):
            if (i, j) == (x, y):
                if grid[i-1][j-1] != '*':
                    return False
            elif grid[i-1][j-1] != '.':
                return False
    return True

def draw_stars(n, m, grid):
    stars = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                for s in range(1, min(i+1, j+1, n-i, m-j) + 1):
                    if is_valid_star(i+1, j+1, s, n, m, grid):
                        stars.append((i+1, j+1, s))
                        for x in range(max(1, i-s), min(n+1, i+s+1)):
                            for y in range(max(1, j-s), min(m+1, j+s+1)):
                                grid[x-1][y-1] = '.'
                        break
                else:
                    return -1
    return stars

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    grid = data[2:]

    stars = draw_stars(n, m, grid)

    if stars == -1:
        print(-1)
    else:
        print(len(stars))
        for star in stars:
            print(star[0], star[1], star[2])

if __name__ == "__main__":
    main()

