import sys

def min_jumps_to_reach_home(n, d, lilies):
    if lilies[0] == '0' or lilies[n-1] == '0':
        return -1

    jumps = [float('inf')] * n
    jumps[0] = 0

    for i in range(n):
        if lilies[i] == '1':
            for j in range(1, d+1):
                if i + j < n:
                    jumps[i + j] = min(jumps[i + j], jumps[i] + 1)

    return jumps[n-1] if jumps[n-1] != float('inf') else -1

