from collections import defaultdict

def max_convenience(n, p):
    graph = defaultdict(list)
    for i in range(n):
        graph[p[i] - 1].append(i)

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    visited = [False] * n
    components = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            components += 1

    if components == 1:
        return n * n
    else:
        return (components - 1) * n + n

