def transform(a, b):
    if b < a:
        return "NO"

    stack = []
    while b >= a:
        stack.append(b)
        if b % 2 == 0:
            b //= 2
        elif b % 10 == 1:
            b //= 10
        else:
            return "NO"

    if stack[-1] != a:
        return "NO"

    return "YES\n{}\n{}".format(len(stack), ' '.join(map(str, stack[::-1])))

