def can_form_substring(order, s1, s2):
    i, j = 0, 0
    while i < len(s1) and j < len(s2):
        if s1[i] == s2[j]:
            i += 1
        j += 1
    return i == len(s1)

def solve(n, strings):
    from functools import cmp_to_key

    def compare(s1, s2):
        if can_form_substring(s1, s1, s2):
            return -1
        elif can_form_substring(s2, s1, s2):
            return 1
        return 0

    sorted_strings = sorted(strings, key=cmp_to_key(compare))
    if all(can_form_substring(sorted_strings[i], sorted_strings[i-1], sorted_strings[i]) for i in range(1, n)):
        return "YES\n" + "\n".join(sorted_strings)
    else:
        return "NO"

