def solve_intervals(n, m, intervals, queries):
    answers = []
    for x, y in queries:
        if x >= y:
            answers.append(-1)
            continue
        covered = False
        for l, r in intervals:
            if r >= x and l <= y:
                covered = True
                break
        if not covered:
            answers.append(-1)
        else:
            answers.append(1)
    return answers

