    from collections import defaultdict

    # Create a set to store the groups where all members are traitors
    traitor_groups = set()

    # Create a dictionary to store the Rick and Morty counts for each universe
    universe_counts = defaultdict(lambda: {'Rick': 0, 'Morty': 0})

    # Process each group
    for group in groups:
        k = group[0]
        members = group[1:]
        rick_count = 0
        morty_count = 0

        for member in members:
            if member < 0:
                universe_counts[-member]['Rick'] += 1
                rick_count += 1
            else:
                universe_counts[member]['Morty'] += 1
                morty_count += 1

        # If all members in the group are traitors, add the group to the set
        if rick_count == k or morty_count == k:
            traitor_groups.add(tuple(sorted(members)))

    # Check if there's any group where all members are traitors in at least one scenario
    for i in range(1 << n):
        current_traitors = set()
        for j in range(n):
