from collections import deque

def min_time_to_turn_off_lights(n, m, floors):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (current_floor, current_room, time)
    visited = set([(0, 0)])

    while queue:
        current_floor, current_room, time = queue.popleft()

        if all(floors[i].count('1') == 0 for i in range(n)):
            return time

        for dr, dc in directions:
            new_room = current_room + dc
            if 0 <= new_room < m + 2:
                if (current_floor, new_room) not in visited:
                    visited.add((current_floor, new_room))
                    if floors[current_floor][new_room] == '1':
                        queue.append((current_floor, new_room, time + 1))
                    else:
                        queue.append((current_floor, new_room, time))

        if current_floor < n - 1:
            if (current_floor + 1, current_room) not in visited:
                visited.add((current_floor + 1, current_room))
                queue.append((current_floor + 1, current_room, time + 1))

        if current_floor > 0:
            if (current_floor - 1, current_room) not in visited:
                visited.add((current_floor - 1, current_room))
                queue.append((current_floor - 1, current_room, time + 1))

