def find_minimum_x(divisors):
    divisors.sort()
    n = len(divisors)
    if n == 1:
        return divisors[0]
    min_x = float('inf')
    for i in range(n):
        x = divisors[i]
        found = True
        for j in range(n):
            if divisors[j] * x != divisors[(j + i) % n] * divisors[(j + i - 1) % n]:
                found = False
                break
        if found:
            min_x = min(min_x, x)
    return min_x if min_x != float('inf') else -1

