def is_tree(n, segments):
    from collections import defaultdict, deque

    # Function to check if two segments intersect and neither is fully inside the other
    def intersect(a, b):
        if a[0] < b[0] < a[1] < b[1] or b[0] < a[0] < b[1] < a[1]:
            return False
        return not (a[0] <= b[0] and a[1] >= b[1]) and not (b[0] <= a[0] and b[1] >= a[1])

    # Create adjacency list
    adj = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if intersect(segments[i], segments[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if the graph is connected and has n-1 edges
    visited = [False] * n
    stack = [0]
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            stack.extend(adj[node])

    return visited.count(True) == n and len(adj[0]) == n - 1

