from collections import Counter

def find_swaps(s, t):
    if s == t:
        return 0, []

    s_count = Counter(s)
    t_count = Counter(t)

    if s_count != t_count:
        return -1, []

    swaps = []
    seen = set()

    for i in range(len(s)):
        if s[i] != t[i] and s[i] not in seen and t[i] not in seen:
            swaps.append((s[i], t[i]))
            seen.add(s[i])
            seen.add(t[i])

    if len(swaps) != len(s_count) // 2:
        return -1, []

    return len(swaps), swaps

