def min_coins_to_cover(n, m, antennas):
    covered = [False] * (m + 1)
    for x, s in antennas:
        start = max(1, x - s)
        end = min(m, x + s)
        for i in range(start, end + 1):
            covered[i] = True

    coins = 0
    for i in range(1, m + 1):
        if not covered[i]:
            for x, s in antennas:
                if x - s <= i <= x + s:
                    covered[i] = True
                    coins += 1
                    break

    return coins

