    n = len(grille)
    decrypted = []
    for _ in range(4):
        for i in range(n):
            for j in range(n):
                if grille[i][j] == '.':
                    decrypted.append(message[i * n + j])
        grille = rotate_grille(grille)
    return ''.join(decrypted)

