from collections import defaultdict

def can_divide_items(N, items, M, suspicious_pairs):
    graph = defaultdict(list)
    for a, b in suspicious_pairs:
        graph[a].append(b)
        graph[b].append(a)

    visited = {item: False for item in items}

    def dfs(node, color):
        if visited[node]:
            return True
        visited[node] = True
        color[node] = not color[node]
        for neighbor in graph[node]:
            if not dfs(neighbor, color):
                return False
        return True

    color = {item: False for item in items}
    for item in items:
        if not visited[item]:
            if not dfs(item, color):
                return "impossible"

    walter_items = [item for item, c in color.items() if c]
    jesse_items = [item for item, c in color.items() if not c]
    return '\n'.join(walter_items) + '\n' + '\n'.join(jesse_items)

