def can_reorder_to_target(n, m, a):
    # Calculate the sum for all possible reorderings
    from itertools import permutations
    for perm in permutations(a):
        total_sum = 0
        for i in range(n):
            inner_sum = 0
            for j in range(i, n):
                inner_sum += perm[j] / (j + 1)
            total_sum += inner_sum
            if total_sum > m:
                break
        if total_sum == m:
            return "YES"
    return "NO"

