from collections import defaultdict, deque
import sys

def find_path(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    stack = [1]
    visited = set([1])
    signposts = [-1] * (n + 1)

    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                signposts[neighbor] = node
                stack.append(neighbor)

    return signposts

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    edges = [(int(data[2 + 2 * i]) + 1, int(data[3 + 2 * i]) + 1) for i in range(m)]

    signposts = find_path(n, m, edges)

    if signposts[1] == -1:
        print("No")
    else:
        print("Yes")
        for i in range(2, n + 1):
            print(signposts[i] - 1)

