from collections import defaultdict

def count_paths(n, m, k, grid):
    dp = defaultdict(int)
    dp[(1, 1)] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i > 1:
                dp[(i, j)] += dp[(i - 1, j)]
            if j > 1:
                dp[(i, j)] += dp[(i, j - 1)]

    total_paths = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            total_paths += dp[(i, j)]

    xor_sum = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            xor_sum ^= grid[i - 1][j - 1]

    if xor_sum == k:
        return total_paths
    else:
        return 0

