def determine_winner(n, ticket):
    left_sum = 0
    right_sum = 0
    erased_count = 0

    # Calculate the sum of the first half and the last half of the ticket
    for i in range(n // 2):
        if ticket[i] != '?':
            left_sum += int(ticket[i])
        else:
            erased_count += 1
    for i in range(n // 2, n):
        if ticket[i] != '?':
            right_sum += int(ticket[i])
        else:
            erased_count += 1

    # If the number of erased digits is not even, Monocarp wins immediately
    if erased_count % 2 != 0:
        return "Monocarp"

    # If the sums of the two halves are already equal, Bicarp wins immediately
    if left_sum == right_sum:
        return "Bicarp"

    # If the difference between the sums is even and there are enough erased digits to balance it, Bicarp wins
    if (left_sum - right_sum) % 2 == 0 and erased_count >= abs(left_sum - right_sum):
        return "Bicarp"

    # Otherwise, Monocarp wins
    return "Monocarp"

