def min_moves_to_divisible_by_25(n):
    n_str = str(n)
    len_n = len(n_str)

    # Check if the number is already divisible by 25
    if int(n_str[-2:]) % 25 == 0:
        return 0

    # Find the positions of the digits 0 and 5
    pos_0 = len_n if '0' not in n_str else n_str.index('0')
    pos_5 = len_n if '5' not in n_str else n_str.index('5')

    # If neither 0 nor 5 is found, it's impossible to make the number divisible by 25
    if pos_0 == len_n and pos_5 == len_n:
        return -1

    # If the number ends in 0, we need to move the last digit to the second last position
    if n_str[-1] == '0':
        if pos_0 != len_n - 1:
            return len_n - 1 - pos_0
        else:
            return -1

    # If the number ends in 5, we need to move the last digit to the second last position
    if n_str[-1] == '5':
        if pos_5 != len_n - 1:
            return len_n - 1 - pos_5
        else:
            return -1

    # If the number ends in a digit other than 0 or 5, we need to find the closest 0 or 5
    if pos_0 < pos_5:
        return len_n - 1 - pos_0
    else:
        return len_n - 1 - pos_5

