def count_emotional_orders(n, a):
    def dp(mask, prev_max, count):
        if mask == (1 << n) - 1:
            return 1
        result = 0
        for i in range(n):
            if not (mask & (1 << i)):
                weight = a[i]
                if weight >= 2 * prev_max or 2 * weight <= prev_max:
                    result = (result + dp(mask | (1 << i), max(prev_max, weight), count + 1)) % MOD
        return result

    return dp(0, 0, 0)

