def min_operations(a, b):
    if a == b:
        return 0
    if a > b:
        return -1
    operations = 0
    while a < b:
        if b % 2 == 0:
            b //= 2
        elif b % 4 == 0:
            b //= 4
        elif b % 8 == 0:
            b //= 8
        else:
            return -1
        operations += 1
    return operations

