from collections import defaultdict, deque

def bfs_distance(tree, start, k):
    n = len(tree)
    dist = [-1] * n
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                if dist[neighbor] <= k:
                    queue.append(neighbor)
                else:
                    break
    return dist

def solve(n, k, edges):
    tree = defaultdict(list)
    for a, b in edges:
        tree[a-1].append(b-1)
        tree[b-1].append(a-1)

    total = 0
    for i in range(n):
        dist = bfs_distance(tree, i, k)
        for j in range(i + 1, n):
            total += dist[j]

    return total

