def matrix_pow(matrix, n):
    result = [[0] * len(matrix) for _ in range(len(matrix))]
    for i in range(len(matrix)):
        result[i][i] = 1
    while n > 0:
        if n % 2 == 1:
            result = matrix_mult(result, matrix)
        matrix = matrix_mult(matrix, matrix)
        n //= 2
    return result

def count_ways(n, adjacency_matrix):
    degree = [sum(row) for row in adjacency_matrix]
    adjacency_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if adjacency_matrix[i][j] == 0:
                adjacency_matrix[i][j] = adjacency_matrix[j][i] = 1
    adjacency_matrix = matrix_pow(adjacency_matrix, n - 1)
    result = 1
    for d in degree:
        result = result * (d - 1) % MOD
    return result

