from typing import List

def calculate_min_distances(n: int, x: List[int], v: List[int]) -> int:
    points = sorted(zip(x, v))
    x, v = zip(*points)
    x = list(x)
    v = list(v)

    def min_distance(i: int, j: int) -> float:
        if v[i] == v[j]:
            return 0
        return abs(x[i] - x[j]) / abs(v[i] - v[j])

    total_distance = 0
    for i in range(n):
        for j in range(i + 1, n):
            total_distance += min_distance(i, j)

    return int(total_distance)

