def max_stair_sequence(cards):
    cards.sort()
    n = len(cards)
    left = [1] * n
    right = [1] * n

    for i in range(1, n):
        if cards[i] > cards[i - 1]:
            left[i] = left[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if cards[i] > cards[i + 1]:
            right[i] = right[i + 1] + 1

    max_length = 0
    best_start = 0
    for i in range(n):
        if left[i] + right[i] - 1 > max_length:
            max_length = left[i] + right[i] - 1
            best_start = i

    stair = []
    for i in range(best_start - left[best_start] + 1, best_start + 1):
        stair.append(cards[i])
    for i in range(best_start + 1, best_start + right[best_start]):
        stair.append(cards[i])

    return max_length, stair

