import sys
from collections import deque

def is_valid(matrix, x, y, h, w, visited):
    return 0 <= x < h and 0 <= y < w and matrix[x][y] == 'X' and not visited[x][y]

def find_polyomino(matrix, h, w):
    visited = [[False for _ in range(w)] for _ in range(h)]
    queue = deque()
    for i in range(h):
        for j in range(w):
            if matrix[i][j] == 'X' and not visited[i][j]:
                queue.append((i, j))
                visited[i][j] = True
                polyomino = [(i, j)]
                while queue:
                    x, y = queue.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if is_valid(matrix, nx, ny, h, w, visited):
                            queue.append((nx, ny))
                            visited[nx][ny] = True
                            polyomino.append((nx, ny))
                return polyomino
    return []

def find_power(matrix, h, w, k):
    polyomino = find_polyomino(matrix, h, w)
    if not polyomino:
        return "No solution"

    polyomino_size = len(polyomino)
    if polyomino_size % k != 0:
        return "No solution"

    smaller_polyomino_size = polyomino_size // k
    smaller_polyomino = [polyomino[i:i + smaller_polyomino_size] for i in range(0, polyomino_size, smaller_polyomino_size)]

    result = [['.' for _ in range(w)] for _ in range(h)]
    for i in range(k):
        for x, y in smaller_polyomino[i]:
            result[x][y] = str(i + 1)

    return '\n'.join(''.join(row) for row in result)

