from fractions import Fraction
from functools import lru_cache

@lru_cache(None)
def dp(red, green, blue, yellow, steps):
    if red == 0 and green == 0 and blue == 0 and yellow == 0:
        return Fraction(1, 1)
    if steps == 0:
        return Fraction(0, 1)
    total = Fraction(0, 1)
    total += dp(red - 1, green, blue, yellow, steps - 1) / 4
    total += dp(red, green - 1, blue, yellow, steps - 1) / 4
    total += dp(red, green, blue - 1, yellow, steps - 1) / 4
    total += dp(red, green, blue, yellow - 1, steps - 1) / 4
    total += dp(red, green, blue, yellow, steps - 1) / 4
    total += dp(red, green, blue, yellow, steps - 1) / 4
    return total

def solve():
    R, G, B, Y, S = map(int, input().split())
