def is_balanced(s: str) -> bool:
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_valid_pairs(n: int, sequences: List[str]) -> int:
    count = 0
    for i in range(n):
        for j in range(n):
            if i != j:
                if is_balanced(sequences[i] + sequences[j]):
                    count += 1
            else:
                if is_balanced(sequences[i] * 2):
                    count += 1
    return count

