def count_paths(N, edges):
    graph = [[] for _ in range(N)]
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    def dfs(path):
        if len(path) == N:
            return 1
        current = path[-1]
        count = 0
        for neighbor in graph[current]:
            if neighbor not in path:
                count += dfs(path + [neighbor])
        return count

    return dfs([0])

