def find_sequence(n, k):
    if n < k:
        return -1
    if n % k == 0:
        return [n // k] * k
    if k == 1:
        return [n]
    if k == 2:
        if n % 2 == 0:
            return [1, n - 1]
        else:
            return [2, n - 2]
    if k == 3:
        if n % 3 == 0:
            return [n // 3, n // 3, n // 3]
        elif n % 3 == 1:
            return [1, n // 3, n // 3 + 1]
        else:
            return [1, n // 3 + 1, n // 3 + 1]
    return -1

