def find_longest_palindrome(strings):
    n, m = len(strings), len(strings[0])
    if n == 1:
        return 2 * m, strings[0] * 2

    for i in range(n):
        for j in range(i + 1, n):
            left = strings[i]
            right = strings[j][::-1]
            if left == right:
                return 2 * m, left * 2

            for k in range(m):
                if left[k:] == right[:m-k]:
                    return 2 * m - k, left + right[k:]
                if left[:m-k] == right[k:]:
                    return 2 * m - k, right + left[k:]

    return 0, ""

