def count_ways(n, a):
    MOD = 10**9 + 7
    count = 0
    for i in range(1, 1 << n):
        product_factors = Counter()
        for j in range(n):
            if i & (1 << j):
                product_factors += Counter(factorization(a[j]))
        if is_square_product(product_factors):
            count += 1
    return count % MOD

def factorization(x):
    factors = []
    # Check for number of 2s in x
    while x % 2 == 0:
        factors.append(2)
        x = x // 2
    # Check for other primes
    for i in range(3, int(x**0.5) + 1, 2):
        while x % i == 0:
            factors.append(i)
            x = x // i
    if x > 2:
        factors.append(x)
    return factors

