def min_crystals(h, n, platforms):
    if n == 0:
        return 0
    if platforms[0] == h:
        platforms[0] -= 1
    crystals = 0
    for i in range(1, n):
        if platforms[i] - platforms[i - 1] > 2:
            crystals += (platforms[i] - platforms[i - 1] - 2) // 2
            platforms[i] = platforms[i - 1] + 2
    if platforms[-1] > 0:
        crystals += platforms[-1]
    return crystals

