def find_max_dima(n, m, table):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    d_positions = []
    for i in range(n):
        for j in range(m):
            if table[i][j] == 'D':
                d_positions.append((i, j))

    def dfs(x, y, count):
        if count == 4:
            return 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and table[nx][ny] == ['I', 'M', 'A'][count % 3]:
                if dfs(nx, ny, count + 1) == 1:
                    return 1
        return 0

    max_count = 0
    for d_x, d_y in d_positions:
        if dfs(d_x, d_y, 0) == 1:
            max_count += 1

    if max_count == 0:
        return "Poor Dima!"
    elif max_count == 1:
        return "Poor Inna!"
    else:
        return max_count

