def max_subset_with_power_of_two_distances(points: List[int]) -> List[int]:
    points_set = set(points)
    dp = defaultdict(int)

    for point in points:
        dp[point] = 1
        for i in range(32):
            if point - (1 << i) in points_set:
                dp[point] = max(dp[point], dp[point - (1 << i)] + 1)

