def can_construct_graph(n, degrees):
    if sum(degrees) % 2 != 0:
        return "NO"

    edges = []
    degree = [0] * n

    for i in range(1, n):
        if degree[i-1] < degrees[i-1]:
            edges.append((1, i+1))
            degree[0] += 1
            degree[i] += 1

    for i in range(n):
        for j in range(i+1, n):
            if degree[i] < degrees[i] and degree[j] < degrees[j]:
                edges.append((i+1, j+1))
                degree[i] += 1
                degree[j] += 1

    if sum(degree) != 2 * len(edges):
        return "NO"

    return "YES", 2, edges

