from heapq import heappop, heappush

def min_unlikeliness(n, k, samples):
    def distance(s1, s2):
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            d = distance(samples[i], samples[j])
            heappush(edges, (d, i, j))

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    total_distance = 0
    mst_edges = []
    while edges and len(mst_edges) < n - 1:
        d, u, v = heappop(edges)
        if find(u) != find(v):
            union(u, v)
            total_distance += d
            mst_edges.append((u, v))

    print(total_distance)
    for u, v in mst_edges:
        print(u, v)

