def are_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    mapping = {}
    mapped = set()
    for char1, char2 in zip(s1, s2):
        if char1 in mapping:
            if mapping[char1] != char2:
                return False
        elif char2 in mapped:
            return False
        else:
            mapping[char1] = char2
            mapped.add(char2)
    return True

