def count_distinct_messages(n, k, links):
    visited = [False] * (n + 1)
    result = []

    def dfs(start):
        if visited[start]:
            return 0
        visited[start] = True
        count = 1
        for i in range(1, k + 1):
            if start - i > 0 and not visited[start - i]:
                count += dfs(start - i)
            if start + i <= n and not visited[start + i]:
                count += dfs(start + i)
        return count

    for i in range(1, n + 1):
        result.append(dfs(i))
        visited = [False] * (n + 1)

    return result

