from collections import defaultdict
from typing import List

def is_consistent(N: int, M: int, pairs: List[List[int]]) -> str:
    graph = defaultdict(list)
    for L, R, D in pairs:
        graph[L].append((R, D))
        graph[R].append((L, -D))

    visited = [False] * (N + 1)
    stack = [(1, 0)]

    while stack:
        node, value = stack.pop()
        if visited[node]:
            continue
        visited[node] = True
        for neighbor, diff in graph[node]:
            if visited[neighbor]:
                if value + diff != visited[neighbor]:
                    return "No"
            else:
                stack.append((neighbor, value + diff))

    return "Yes"

