def game_winner(x_p, y_p, x_v, y_v):
    p1_moves = [(-1, 0), (0, -1)]
    p2_moves = [(-1, 0), (-1, -1), (0, -1)]

    def manhattan_distance(x, y):
        return abs(x) + abs(y)

    def can_reach_zero(x, y):
        return manhattan_distance(x, y) <= manhattan_distance(0, 0)

    p1_can_win = any(can_reach_zero(x_p + dx, y_p + dy) for dx, dy in p1_moves) or \
                 any(can_reach_zero(x_p - dx, y_p - dy) for dx, dy in p1_moves)

    p2_can_win = any(can_reach_zero(x_v + dx, y_v + dy) for dx, dy in p2_moves) or \
                 any(can_reach_zero(x_v - dx, y_v - dy) for dx, dy in p2_moves)

    return "Polycarp" if p1_can_win and not p2_can_win else "Vasiliy" if p2_can_win and not p1_can_win else "Polycarp"

