def decode_message(N, D, encoded):
    p_A = D / 8
    p_B = 1 - p_A
    a, b = 0, 1
    message = []

    for bit in encoded[2:]:
        if bit == '0':
            a += p_A * (b - a)
        else:
            b = a + p_A * (b - a)
        message.append('A' if a < b else 'B')

    return ''.join(message[::-1])

