import math

def find_possible_m(n, a):
    max_num = a[-1]
    if max_num == 1:
        return [1]
    if max_num < (1 << (int(math.log2(max_num)) + 1)) - 1:
        return [-1]

    possible_m = []
    for k in range(int(math.log2(max_num)) + 1):
        count = 0
        current_sum = 0
        for num in a:
            if num == (1 << k) - 1:
                count += 1
                current_sum += num
            else:
                if current_sum + num > (1 << k) - 1:
                    break
                else:
                    count += 1
                    current_sum += num
        if current_sum == (1 << (k + 1)) - 2:
            possible_m.append(count)

    return possible_m if possible_m else [-1]

