def reconstruct_weights(n):
    weights = [0] * (1 << n)
    for i in range(1 << n):
        weights[i] = int(input())

    weights.sort()

    for i in range(weights[-1] // 2 + 1):
        if i not in weights:
            return "impossible"

    def backtrack(start, remaining):
        if remaining == 0:
            return True
        if start == len(weights) - 1:
            return False

        for i in range(start, len(weights)):
            if weights[i] <= remaining:
                if backtrack(i + 1, remaining - weights[i]):
                    return True
                weights[i], weights[start] = weights[start], weights[i]
        return False

    if backtrack(0, weights[-1]):
        for w in sorted(weights[:-1]):
            print(w)
    else:
        print("impossible")

