MOD = 1000000007

def minesweeper_1d(s):
    n = len(s)
    dp = [0] * (n + 1)
    dp[n] = 1  # One way to have an empty field

    for i in range(n-1, -1, -1):
        if s[i] == '*':
            dp[i] = dp[i+1]
        elif s[i] == '?':
            dp[i] = (dp[i+1] * 3) % MOD
        else:
            dp[i] = dp[i+1] if s[i] == '?' else 0
            if i < n-1 and s[i+1] == '*':
                dp[i] = (dp[i] + dp[i+2]) % MOD
            elif i < n-1 and '1' <= s[i+1] <= '2':
                dp[i] = (dp[i] + dp[i+2]) % MOD

    return dp[0]

