def count_consecutive_seats(n, m, k, matrix):
    ways = 0
    for i in range(n):
        row_ways = 0
        for j in range(m):
            if matrix[i][j] == '.':
                if j >= k:
                    if matrix[i][j - k] == '.':
                        row_ways += 1
            else:
                row_ways = 0
        ways += row_ways * (sum(1 for j in range(m - k + 1) if matrix[i][j] == '.') + row_ways)

    for j in range(m):
        col_ways = 0
        for i in range(n):
            if matrix[i][j] == '.':
                if i >= k:
                    if matrix[i - k][j] == '.':
                        col_ways += 1
            else:
                col_ways = 0
        ways += col_ways * (sum(1 for i in range(n - k + 1) if matrix[i][j] == '.') + col_ways)

    return ways

