def min_jedi_to_remove(n, m, sabers, desired_counts):
    count = [0] * (m + 1)
    result = 0
    count_window = 0
    left = 0

    for right in range(n):
        current_color = sabers[right]
        count[current_color] += 1

        if count[current_color] == desired_counts[current_color - 1]:
            count_window += 1

        while count_window == m:
            if right - left + 1 < n:
                result = max(result, right - left + 1)
            current_color_at_left = sabers[left]
            count[current_color_at_left] -= 1
            if count[current_color_at_left] < desired_counts[current_color_at_left - 1]:
                count_window -= 1
            left += 1

    if result == 0:
        return -1
    else:
        return n - result

