def min_lcm(n, a):
    from math import gcd
    min_val = float('inf')
    result = None
    for i in range(n):
        for j in range(i+1, n):
            curr_lcm = a[i] * a[j] // gcd(a[i], a[j])
            if curr_lcm < min_val:
                min_val = curr_lcm
                result = (i, j)
    return result if min_val != 1 else (0, 1)

