def beauty_of_array(n, m, k, a):
    beauty = 0
    count = {}
    for i in range(n):
        remainder = a[i] % k
        if remainder in count:
            count[remainder][0] += 1
            count[remainder][1] = i
        else:
            count[remainder] = [1, i]
        beauty = max(beauty, count[remainder][0])

    for i in range(1, k):
        if i not in count:
            continue
        l, r = count[i]
        if l == 0:
            count[i] = [1, r]
        elif r == n - 1:
            count[i] = [l, n - 1]
        else:
            if a[l - 1] % k != i:
                count[i] = [l, count[i][1]]
            if a[r + 1] % k != i:
                count[i] = [count[i][0], r]
        beauty = max(beauty, count[i][1] - count[i][0] + 1)

    return min(beauty, m)

