from collections import defaultdict
from typing import List

def bfs(graph: defaultdict, start: tuple, visited: set, n: int, m: int) -> List[List[bool]]:
    queue = [start]
    visited.add(start)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    lake = [[False] * m for _ in range(n)]
    lake[start[0]][start[1]] = True

    while queue:
        x, y = queue.pop(0)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and graph[(nx, ny)]:
                visited.add((nx, ny))
                queue.append((nx, ny))
                lake[nx][ny] = True

    return lake

def minimize_lakes(n: int, m: int, k: int, map_data: List[str]) -> int:
    graph = defaultdict(bool, {(i, j): map_data[i][j] == '.' for i in range(n) for j in range(m)})
    visited = set()
    lakes = []

    for i in range(n):
        for j in range(m):
            if (i, j) not in visited and map_data[i][j] == '.':
                lake = bfs(graph, (i, j), visited, n, m)
                lakes.append(lake)

    lakes.sort(key=lambda x: len(x))

    fill_count = 0
    for lake in lakes[:-k]:
        for i in range(n):
            for j in range(m):
                if lake[i][j]:
                    map_data[i][j] = '*'
                    fill_count += 1

    return fill_count

