def solve(n, m, forbidden):
    sequence = []
    used = [False] * m
    for i in range(m):
        if used[i]:
            continue
        if i == 0 or not any(i * prev % m in forbidden for prev in sequence):
            sequence.append(i)
            for prev in sequence:
                used[i * prev % m] = True
    return f"{len(sequence)}\n{' '.join(map(str, sequence))}"

