def min_watering_operations(n, h):
    operations = 0
    current_max = 0
    for i in range(n):
        current_max = max(current_max, i+1)
        if i+1 > current_max:
            operations += 1
    if all(height == 0 for height in h):
        operations += 1
    return operations

