def catalan(n):
    if n == 0:
        return 1
    catalan = [0 for _ in range(n+1)]
    catalan[0] = 1
    catalan[1] = 1

    for i in range(2, n+1):
        catalan[i] = 0
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i-j-1]

    return catalan[n]

def square_catalan(n):
    return sum(catalan(k) * catalan(n-k) for k in range(n+1))

