def longest_increasing_subsequence(a):
    n = len(a)
    tails = []
    indices = []

    for i in range(n):
        if not tails or a[i] > tails[-1]:
            tails.append(a[i])
            indices.append(i+1)
        else:
            l, r = 0, len(tails) - 1
            while l < r:
                m = (l + r) // 2
                if tails[m] < a[i]:
                    l = m + 1
                else:
                    r = m
            if tails[l] < a[i]:
                tails[l] = a[i]
                indices[l] = i + 1
            else:
                tails.insert(l, a[i])
                indices.insert(l, i + 1)

    max_length = len(tails)
    result = [3] * n
    for i, x in enumerate(a):
        pos = tails.index(x)
        if pos == 0 or pos == max_length - 1:
            result[i] = 1
        elif max_length - pos == 1:
            result[i] = 2

    return ''.join(map(str, result))

