def predict_vote(order, employees):
    depublicans = set()
    remocrats = set()
    for i in range(len(order)):
        if employees[i] == 'D':
            depublicans.add(i)
        else:
            remocrats.add(i)

    depublicans_index = 0
    remocrats_index = 0

    while len(depublicans) > 1 and len(remocrats) > 1:
        if depublicans_index < len(order) and order[depublicans_index] in depublicans:
            depublicans.remove(order[depublicans_index])
            remocrats.add(order[depublicans_index])
            depublicans_index += 1
        else:
            depublicans_index += 1

        if remocrats_index < len(order) and order[remocrats_index] in remocrats:
            remocrats.remove(order[remocrats_index])
            depublicans.add(order[remocrats_index])
            remocrats_index += 1
        else:
            remocrats_index += 1

    return 'D' if len(depublicans) == 1 else 'R'

