def min_moves(n, m, i, j, a, b):
    corners = [(1, m), (n, 1), (n, m), (1, 1)]
    moves = float('inf')
    for corner in corners:
        dx, dy = corner[0] - i, corner[1] - j
        if dx % a == 0 and dy % b == 0:
            x, y = abs(dx // a), abs(dy // b)
            if x + y < moves:
                moves = x + y
    return moves if moves != float('inf') else "Poor Inna and pony!"

