def cubes_sum(n):
    cubes = [i**3 for i in range(1, int((n**0.5)) + 1)]
    sums = set()
    for i in range(len(cubes)):
        for j in range(i, len(cubes)):
            if cubes[i] + cubes[j] <= n:
                sums.add(cubes[i] + cubes[j])
            else:
                break
    return sums

def largest_bus_number(m):
    bus_numbers = set()
    for i in range(1, m):
        bus_numbers |= cubes_sum(i)
    bus_numbers = [num for num in bus_numbers if num >= 2]
    bus_numbers.sort(reverse=True)
    return bus_numbers[0] if bus_numbers else None

