def car_fines(n, entry, exit):
    entry_dict = {car: idx for idx, car in enumerate(entry)}
    exit_dict = {car: idx for idx, car in enumerate(exit)}
    fined_cars = set()

    for car in entry:
        if exit_dict[car] < entry_dict[car]:
