def max_cookies(n, k, a, b):
    a = list(zip(a, b))
    a.sort(key=lambda x: x[0])
    max_cookies, cookies, magic = 0, 0, k
    for req, have in a:
        if req > have:
            diff = req - have
            if magic < diff:
                return max_cookies
            magic -= diff
            cookies += diff
        cookies += have
        if cookies * a[0][0] <= k:
            max_cookies = cookies // (a[0][0] * n)
            if cookies % (a[0][0] * n) != 0:
                max_cookies += 1
        else:
