def count_attacking_pairs(n, bishops):
    diagonals = {}
    for x, y in bishops:
        diagonal1 = x - y
        diagonal2 = x + y
        if diagonal1 not in diagonals:
            diagonals[diagonal1] = 0
        if diagonal2 not in diagonals:
            diagonals[diagonal2] = 0
        diagonals[diagonal1] += 1
        diagonals[diagonal2] += 1

    pairs = 0
    for count in diagonals.values():
        pairs += count * (count - 1) // 2
    return pairs

