from collections import deque

def min_steps_to_reach(N, board):
    directions = [(-2, -1), (-2, 1), (2, -1), (2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2)]
    visited = [[False]*N for _ in range(N)]
    steps = 0

    start_r, start_c = -1, -1
    for r in range(N):
        for c in range(N):
            if board[r][c] == 'K':
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    if start_r == -1:
        return -1

    queue = deque([(start_r, start_c, 0)])
    visited[start_r][start_c] = True

    while queue:
        for _ in range(len(queue)):
            r, c, step = queue.popleft()
            if (r, c) == (0, 0):
                return step

            for dr, dc in directions:
                new_r, new_c = r + dr, c + dc
                while 0 <= new_r < N and 0 <= new_c < N and not visited[new_r][new_c] and board[new_r][new_c] != '#':
                    new_r, new_c = new_r + dr, new_c + dc
                if 0 <= new_r < N and 0 <= new_c < N and not visited[new_r][new_c] and board[new_r][new_c] != '#':
                    visited[new_r][new_c] = True
                    queue.append((new_r, new_c, step + 1))

