def count_special_elements(a):
    n = len(a)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + a[i]

    special_elements = set()

    for l in range(n):
        for r in range(l + 1, n):
            curr_sum = prefix_sum[r + 1] - prefix_sum[l]
            if curr_sum > n:
                break
            special_elements.add(curr_sum)

    return sum(1 for x in a if x in special_elements)


