import sys
import math

def read_graph(n, m, lines):
    graph = [[] for _ in range(n)]
    for line in lines:
        u, v = map(int, line.split())
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
    return graph

def find_independent_set(n, graph):
    independent_set = []
    visited = [False] * n
    queue = [0]
    while queue:
        node = queue.pop(0)
        if not visited[node]:
            independent_set.append(node)
            visited[node] = True
            for neighbor in graph[node]:
                visited[neighbor] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                queue.append(neighbor)
    return independent_set[:math.ceil(math.sqrt(n))]

def find_cycle(n, graph):
    visited = [False] * n
    queue = [0]
    prev = [-1] * n
    while queue:
        node = queue.pop(0)
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    queue.append(neighbor)
                    prev[neighbor] = node
                elif prev[node] != neighbor:
                    cycle = [node]
                    while cycle[-1] != neighbor:
                        cycle.append(prev[cycle[-1]])
                    cycle.append(neighbor)
                    return cycle
    return []

def main():
    n, m = map(int, sys.stdin.readline().split())
    lines = sys.stdin.readlines()
    graph = read_graph(n, m, lines)

    independent_set = find_independent_set(n, graph)
    if independent_set:
        print(1)
        print(*independent_set)
    else:
        cycle = find_cycle(n, graph)
        if cycle:
            print(2)
            print(len(cycle))
            print(*cycle)

if __name__ == "__main__":
    main()

