def min_t(n: int, points: List[Tuple[int, int]]) -> int:
    if n <= 2:
        return 1

    x_coords, y_coords = zip(*points)
    unique_x = sorted(set(x_coords))
    unique_y = sorted(set(y_coords))

    max_x_diff = unique_x[-1] - unique_x[0]
    max_y_diff = unique_y[-1] - unique_y[0]

    for i in range(len(unique_x) - 1):
        if unique_x[i + 1] - unique_x[i] > max_x_diff:
            max_x_diff = unique_x[i + 1] - unique_x[i]

    for i in range(len(unique_y) - 1):
        if unique_y[i + 1] - unique_y[i] > max_y_diff:
            max_y_diff = unique_y[i + 1] - unique_y[i]

    if max_x_diff >= max_y_diff:
        # Align points based on x-coordinates
        aligned_points = [(x, y) for x, y in points if unique_x[0] <= x <= unique_x[-1]]
        min_x, max_x = unique_x[0], unique_x[-1]

        for i in range(len(aligned_points)):
            for j in range(i + 1, len(aligned_points)):
                dx = aligned_points[j][0] - aligned_points[i][0]
                dy = aligned_points[j][1] - aligned_points[i][1]

                if dx % max_x_diff == 0 and dy % max_x_diff == 0:
                    return max(max_x_diff, abs(dy) // max_x_diff + abs(dx) // max_x_diff)
    else:
        # Align points based on y-coordinates
        aligned_points = [(x, y) for x, y in points if unique_y[0] <= y <= unique_y[-1]]
        min_y, max_y = unique_y[0], unique_y[-1]

        for i in range(len(aligned_points)):
            for j in range(i + 1, len(aligned_points)):
                dx = aligned_points[j][0] - aligned_points[i][0]
                dy = aligned_points[j][1] - aligned_points[i][1]

                if dx % max_y_diff == 0 and dy % max_y_diff == 0:
                    return max(max_y_diff, abs(dx) // max_y_diff + abs(dy) // max_y_diff)

    return -1

