def min_time_to_turn_off_lights(n, m, building):
    time = 0
    for floor in range(n - 1, -1, -1):
        for room in range(m):
            if building[floor][room] == '1':
                if floor < n - 1:
                    # move to next floor
                    time += 2
                    # move to the room
                    time += 2 * room
                else:
                    # move to the room
                    time += 2 * room
        if floor > 0:
            # move to the next floor
            time += 2
    return time

