def min_word(word):
    n = len(word)
    min_word = word
    for i in range(n-1):
        for j in range(i+1, n):
            new_word = word[:i] + word[i:j][::-1] + word[j:]
            if new_word < min_word:
                min_word = new_word
    return min_word

