from itertools import combinations

def possible_placements(n, k, grid, sizes):
    count = 0
    for size in sizes:
        for start in combinations(range(n*n), size):
            if all(grid[y//n][y%n] == '.' for y in start):
                for dy, dx in combinations(range(1, size), 2):
                    if (start[dy]//n == start[dx]//n and abs(start[dy]%n - start[dx]%n) == 1) or \
                       (start[dy]%n == start[dx]%n and abs(start[dy]//n - start[dx]//n) == 1):
                        break
                else:
                    count += 1
    return count

