    empty1, empty2 = find_empty(grid1), find_empty(grid2)
    moves = []
    if empty1[0] == empty2[0]:
        if empty1[1] == empty2[1]:
            for _ in range(3):
                grid2[empty2[0]][empty2[1]] = grid1[empty1[0]][empty1[1]]
                empty2 = (empty2[0] + 1) % 2, empty2[1]
                if grid2[empty2[0]][empty2[1]] == 'X':
                    empty2 = (empty2[0] - 1) % 2, empty2[1]
                moves.append('D' if empty2[0] > empty1[0] else 'U')
        elif empty1[1] == empty2[1] + 1:
            for _ in range(3):
                grid2[empty2[0]][empty2[1]] = grid1[empty1[0]][empty1[1]]
                empty2 = empty1[0], (empty1[1] + 1) % 2
                moves.append('R')
        elif empty1[1] == empty2[1] - 1:
            for _ in range(3):
                grid2[empty2[0]][empty2[1]] = grid1[empty1[0]][empty1[1]]
                empty2 = empty1[0], (empty1[1] - 1) % 2
                moves.append('L')
    else:
        if empty1[0] == empty2[0] + 1:
            for _ in range(3):
