def vasya_reading():
    import sys
    input = sys.stdin.readline

    t = int(input())

    for _ in range(t):
        n, x, y, d = map(int, input().split())

        if abs(x - y) % d == 0:
            print(abs(x - y) // d)
        elif abs(y - 1) % d == 0 or abs(n - y) % d == 0:
            print(-1)
        else:
            if x > y:
                x, y = n - x + 1, n - y + 1

            if abs(y - 1) % d == 0:
                print(abs(x - y) // d + 2)
            elif abs(n - y) % d == 0:
                print(abs(x - y) // d + 2)
            else:
                print(-1)

