def palindromic_characters(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    result = [0] * n

    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if s[start] == s[end]:
                if length == 2:
                    dp[start][end] = 1
                else:
                    dp[start][end] = dp[start + 1][end - 1]
            result[length - 1] += dp[start][end]

    return result

