import sys

MOD = 998244353

def factorial_mod(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def binomial_mod(n, k, mod):
    if k > n:
        return 0
    k = min(k, n - k)
    numerator = 1
    for i in range(k):
        numerator = (numerator * (n - i)) % mod
    denominator = factorial_mod(k, mod)
    return (numerator * pow(denominator, mod - 2, mod)) % mod

def count_ways(n, m, c):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length
            for split in range(start + 1, end):
                dp[start][end] = (dp[start][end] + dp[start][split] * dp[split][end] * binomial_mod(end - start, length - 1, MOD)) % MOD
    return dp[0][n]

