from collections import deque

def bfs(H, W, K, sx, sy, gx, gy):
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[float('inf')] * W for _ in range(H)]
    visited[sx - 1][sy - 1] = 0
    q = deque([(sx - 1, sy - 1)])

    while q:
        x, y = q.popleft()
        if x == gx - 1 and y == gy - 1:
            return visited[x][y]
        for dx, dy in directions:
            for k in range(1, K + 1):
                nx, ny = x, y
                while 0 <= nx + k * dx < H and 0 <= ny + k * dy < W and (nx + k * dx, ny + k * dy) not in [(i, j) for i in range(H) for j in range(W) if visited[i][j] < float('inf')]:
                    nx, ny = nx + k * dx, ny + k * dy
                if (nx, ny) == (gx - 1, gy - 1):
                    return visited[x][y] + 1
                if visited[nx][ny] > visited[x][y] + 1:
                    visited[nx][ny] = visited[x][y] + 1
                    q.append((nx, ny))
    return -1

