from typing import List

def solve(n: int, a: List[int], queries: List[int]) -> List[int]:
    # Precompute prefix gcd array
    prefix_gcd = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_gcd[i] = gcd(prefix_gcd[i - 1], a[i - 1])

    # Create a dictionary to store frequency of each gcd
    gcd_freq = {}
    for i in range(1, n + 1):
        curr_gcd = prefix_gcd[i]
        if curr_gcd not in gcd_freq:
            gcd_freq[curr_gcd] = 0
        gcd_freq[curr_gcd] += 1

    # Answer each query
    answers = []
    for query in queries:
        if query in gcd_freq:
            answers.append(gcd_freq[query])
        else:
            answers.append(0)

    return answers

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

