from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def solution(n, m, field):
    parent = list(range(n * m))
    rank = [0] * (n * m)

    # Build graph and find connected components
    for i in range(n):
        for j in range(m):
            if field[i][j] == '*':
                continue
            if i > 0 and field[i-1][j] == '.':
                union(parent, rank, i*m + j, (i-1)*m + j)
            if i < n-1 and field[i+1][j] == '.':
                union(parent, rank, i*m + j, (i+1)*m + j)
            if j > 0 and field[i][j-1] == '.':
                union(parent, rank, i*m + j, i*m + j - 1)
            if j < m-1 and field[i][j+1] == '.':
                union(parent, rank, i*m + j, i*m + j + 1)

    # Calculate the size of each connected component for each impassable cell
    result = [['.'] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if field[i][j] == '*':
                component_size = 0
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < n and 0 <= ny < m and field[nx][ny] == '.':
                            component_size += 1
                            union(parent, rank, i*m + j, nx*m + ny)
                result[i][j] = str(component_size % 10)

    # Print the result
    return '\n'.join([''.join(row) for row in result])

