def count_paths(n, grid):
    mod = 2**31 - 1
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1 if grid[0][0] == '.' else 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % mod
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % mod

    if dp[n-1][n-1] == 0:
        can_go_left_up = ((grid[0][0] == '.') and (grid[n-1][n-1] == '.'))
        can_go_right_down = (all(grid[i][j] == '.' for i in range(n) for j in range(n) if (i,j) != (0,0) and (i,j) != (n-1,n-1)))
        if can_go_left_up and can_go_right_down:
            return "THE GAME IS A LIE"
        else:
            return "INCONCEIVABLE"
    else:
        return dp[n-1][n-1]

