def bracket_sequence(s):
    n = len(s)
    dp = [[[0]*2 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i][0] = dp[i][i][1] = 1
    for length in range(2, n+1, 2):
        for i in range(n-length+1):
            j = i + length - 1
            for k in range(i, j+1):
                if s[k] in '([{' and (s[k] == '(' and s[j] == ')' or s[k] == '[' and s[j] == ']' or s[k] == '{' and s[j] == '}'):
                    dp[i][j][0] += dp[i][k-1][1] * dp[k+1][j][1]
                if s[k] == '?' and (s[k] == '(' or s[k] == '[' or s[k] == '{'):
                    dp[i][j][1] += dp[i][k-1][0] * dp[k+1][j][1]
                if s[k] == '?' and (s[k] == ')' or s[k] == ']' or s[k] == '}'):
                    dp[i][j][1] += dp[i][k-1][1] * dp[k+1][j][0]
    return str(dp[0][n-1][0] + dp[0][n-1][1])[-5:]

