def gcd_operations(n, a):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    current_gcd = a[0]
    for i in range(1, n):
        current_gcd = gcd(current_gcd, a[i])

    if current_gcd != 1:
        return 0

    operations = 0
    for i in range(n):
        if a[i] % current_gcd == 0:
            continue
        operations += min(a[i] % current_gcd, current_gcd - a[i] % current_gcd)
        a[i] += min(a[i] % current_gcd, current_gcd - a[i] % current_gcd)

    return operations

