def prime_factors(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def f(x, p):
    power = 0
    while p % x == 0:
        p //= x
        power += 1
    return power

def solution(x, n):
    MOD = 10**9 + 7
    result = 1
    for p in prime_factors(x):
        power = f(p, n)
        result = (result * pow(p, power, MOD)) % MOD
    return result

