from collections import defaultdict

def floyd_warshall(n, edges):
    dist = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    for u, v, x in edges:
        dist[u-1][v-1] = x
        dist[v-1][u-1] = x

    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

