def champagne_flow(n, t):
    pyramid = [[0] * i for i in range(1, n+1)]
    full_glasses = 0

    for _ in range(t):
        for i in range(n):
            if pyramid[i][0] < 1:
                pyramid[i][0] += 1
                full_glasses += 1
            else:
                overflow = pyramid[i][0] - 1
                pyramid[i][0] = 1
                if i > 0:
                    pyramid[i-1][0] += overflow // 2
                    if overflow % 2 != 0:
                        pyramid[i][1] += 1
                        full_glasses += 1
                else:
                    full_glasses += 1

    return full_glasses

