def ways_to_connect(n, a):
    mod = 10**9 + 7
    dp = [[0]*n for _ in range(n)]

    # Base case: connecting 2 points
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp table
    for k in range(2, n):
        for i in range(n):
            j = (i + k) % n
            if a[i][j] == 1:
                dp[i][j] = (dp[i][(j-1)%n] + dp[(i+1)%n][j]) % mod
            else:
                dp[i][j] = (2*dp[i][(j-1)%n] + 2*dp[(i+1)%n][j] - dp[i][(j-2)%n] - dp[(i+2)%n][j]) % mod

    return dp[0][(n-1)%n]

