def longest_subarray(n, x, a):
    max_length = -1
    prefix_sum = 0
    prefix_sum_mod = {0: -1}

    for i in range(n):
        prefix_sum += a[i]
        if x != 0:
            prefix_sum %= x

        if prefix_sum in prefix_sum_mod:
            max_length = max(max_length, i - prefix_sum_mod[prefix_sum])
        else:
            prefix_sum_mod[prefix_sum] = i

    return max_length

