def nim_status(positions, S):
    memo = {}

    def dp(position):
        if position in memo:
            return memo[position]
        for s in S:
            if position - s >= 0:
                if not dp(position - s):
                    memo[position] = False
                    return False
        memo[position] = True
        return True

    for position in positions:
        print('W' if dp(position) else 'L')

