def generate_crossword(A, B):
    N, M = len(A), len(B)
    common_letter = next(filter(lambda x: x in A and x in B, set(A) & set(B)))
    crossword = [['.' for _ in range(N)] for _ in range(M)]

    # Place A
    for i, char in enumerate(A):
        if char == common_letter:
            crossword[0][i] = char

    # Place B
    for i, char in enumerate(B):
        if char == common_letter:
            crossword[i][0] = char

    return crossword

