def solve(n):
    if n <= 1:
        return -1

    board = [[0] * n for _ in range(n)]
    x, y = 0, 0
    num = 1

    while num <= n * n:
        board[x][y] = num
        num += 1

        # rook move: down, right
        nx, ny = x + 1, y + 1
        while 0 <= nx < n and 0 <= ny < n and board[nx][ny] != 0:
            nx, ny = nx + 1, ny + 1
        if 0 <= nx < n and 0 <= ny < n and board[nx][ny] == 0:
            x, y = nx, ny
        else:
            x, y = (x + 1) % n, (y + 1) % n

        # queen move: any direction
        dx, dy = [0, 1, 0, 1], [1, 0, -1, 0]
        for i in range(4):
            while 0 <= x + dx[i] < n and 0 <= y + dy[i] < n and board[x + dx[i]][y + dy[i]] != 0:
                x, y = x + dx[i], y + dy[i]
            if 0 <= x + dx[i] < n and 0 <= y + dy[i] < n and board[x + dx[i]][y + dy[i]] == 0:
                x, y = x + dx[i], y + dy[i]
            else:
                break

    if board[-1][-1] != n * n:
        return -1

    return "\n".join([" ".join(map(str, row)) for row in board])

