def solve(n, a, MOD=10**9 + 7):
    prime_powers = [0] * 71
    for i in range(2, 71):
        if not prime_powers[i]:
            for j in range(i, 71, i):
                prime_powers[j] += 1

    dp = [1] * 71
    for num in a:
        for j in range(num, 0, -1):
            dp[j] += dp[j - 1]

    ans = 0
    for i in range(1, 71):
        if prime_powers[i]:
            ans += dp[i] * (2 ** (prime_powers[i] - 1)) % MOD
            ans %= MOD

    return (ans - 1) % MOD

