def find_equivalence_classes(passwords):
    parents = {password: password for password in passwords}

    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parents[root_y] = root_x

    for i in range(len(passwords)):
        for j in range(i + 1, len(passwords)):
            if not set(passwords[i]).isdisjoint(set(passwords[j])):
                union(passwords[i], passwords[j])

    equivalence_classes = {}
    for password in passwords:
        root = find(password)
        if root not in equivalence_classes:
            equivalence_classes[root] = []
        equivalence_classes[root].append(password)

    return len(equivalence_classes)

