def withdraw(n):
    # Initialize the dp array with a large number
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # No operations needed to withdraw 0 yen

    # Generate the powers of 6 and 9
    powers_of_6 = [6 ** i for i in range(9)]
    powers_of_9 = [9 ** i for i in range(10)]

    # Update the dp array
    for power in powers_of_6:
        for i in range(power, n + 1):
            dp[i] = min(dp[i], dp[i - power] + 1)

    for power in powers_of_9:
        for i in range(power, n + 1):
            dp[i] = min(dp[i], dp[i - power] + 1)

    if n == 100000:
        return dp[n] + 1
    else:
        return dp[n]

