def count_words_in_parentheses(s):
    words_outside = []
    words_inside = []
    word = ""
    in_parentheses = False

    for char in s:
        if char.isalpha():
            word += char
        elif char == "(":
            if word:
                words_outside.append(word)
                word = ""
            in_parentheses = True
        elif char == ")":
            if word:
                words_inside.append(word)
                word = ""
            in_parentheses = False
        elif char == "_":
            if word:
                if in_parentheses:
                    words_inside.append(word)
                else:
                    words_outside.append(word)
                word = ""

    if word:
        if in_parentheses:
            words_inside.append(word)
        else:
            words_outside.append(word)

    longest_word_outside = max((len(word) for word in words_outside), default=0)
    num_words_inside = len(words_inside)

    return f"{longest_word_outside} {num_words_inside}"

