def min_removals(n, a):
    target = [4, 8, 15, 16, 23, 42]
    count = [0] * 6
    result = 0
    for num in a:
        if num in target:
            index = target.index(num)
            if count[index] == 0:
                result += count[0]  # Add removals needed for previous sequences
            count[index] += 1
            if count[index] == 6:  # A full sequence is formed
                for i in range(6):
                    count[i] = 0  # Reset the counts for the next sequence
    # Add removals needed for incomplete sequences
    for i in range(6):
        result += count[i] * (6 - count[i])
    return result

