import sympy

def create_prime_degree_graph(n):
    if n < 3:
        return -1

    edges = []
    for i in range(1, n):
        # Start with an edge from vertex 1 to i
        edges.append((1, i+1))
        # Continue adding edges to maintain prime degree
        for j in range(i+2, n+1):
            if sympy.isprime(i) and sympy.isprime(j) and sympy.isprime(n-1):
                edges.append((i+1, j))
                i += 1

    # Check if total number of edges is prime
    total_edges = len(edges)
    if total_edges > 1 and sympy.isprime(total_edges):
        return total_edges, edges
    else:
        return -1

def main():
    n = int(input())
    result = create_prime_degree_graph(n)
    if result == -1:
        print(-1)
    else:
        print(*result)

if __name__ == "__main__":
    main()

