def min_operations(n, s, t):
    count_s, count_t = 0, 0
    for i in range(n):
        if s[i] == '1':
            count_s += 1
        if t[i] == '1':
            count_t += 1
    if count_s != count_t:
        return -1
    operations = 0
    s_ones = []
    t_ones = []
    for i in range(n):
        if s[i] == '1':
            s_ones.append(i)
        if t[i] == '1':
            t_ones.append(i)
    i, j = 0, 0
    while i < len(s_ones) and j < len(t_ones):
        if abs(s_ones[i] - t_ones[j]) % n == 1:
            i += 1
            j += 1
        else:
            j += 1
            operations += 1
    return operations

